INSERT INTO `entries` (`id`, `site`, `origin_id`, `published`, `status`, `slug`, `uri`, `date`, `order`, `collection`, `blueprint`, `data`, `schema`, `seo`, `created_at`, `updated_at`) VALUES
('01a0b382-6875-7045-aa28-6c187e7728f7', 'default', NULL, 1, 'published', 'home', '', '2026-09-21 13:31', 1, 'pages', 'homepage', '{\"title\": \"Home\", \"hero_loop\": [{\"_enabled\": true, \"hero_desc\": \"Masuki dunia yang imersif, ungkap rahasia tersembunyi, dan alami petualangan tak terlupakan melalui game yang dibuat oleh Aknesia.\", \"hero_image\": [11], \"hero_label\": \"Permainan Dimulai dengan Sebuah Misteri\"}, {\"_enabled\": true, \"hero_desc\": \"Jelajahi berbagai game karya Aknesia yang menghadirkan dunia menarik, gameplay kreatif, dan pengalaman bermain yang berkesan.\", \"hero_image\": [9], \"hero_label\": \"Temukan Pengalaman Bermain yang Berbeda\"}, {\"_enabled\": true, \"hero_desc\": \"Jelajahi pengalaman bermain game yang unik dan dunia imajinatif yang diciptakan oleh Aknesia. Temukan petualangan baru, kisah tak terlupakan, dan game yang dirancang untuk menginspirasi para pemain.\", \"hero_image\": [10], \"hero_label\": \"Temukan Dunia di Luar Imajinasi\"}], \"hero_cta_link\": \"entry::01a13891-699a-70c1-bbeb-7aebf3bd4423\", \"overview_desc\": \"<p>Aksnesia adalah pengembang game yang menghadirkan <a target=\\\"_blank\\\" rel=\\\"noopener noreferrer nofollow\\\" href=\\\"#\\\">karya orisinal</a> dengan ide kreatif yang dirancang untuk memberikan kesan tersendiri bagi setiap pemain.</p>\", \"hero_cta_label\": \"Jelajahi Sekarang\", \"overview_image\": [12], \"overview_heading\": \"Aksnesia menghadirkan game dengan dunia yang menarik, pengalaman bermain yang berbeda, dan cerita yang meninggalkan kesan bagi setiap pemain.\", \"news_section_label\": \"Berita\", \"news_section_heading\": \"Ikuti informasi terbaru dari kami\"}', '[]', '{\"robots\": [\"nofollow\", \"noarchive\"], \"meta_title\": \"Welcome to Laravel\", \"meta_author\": \"01a0c190-2139-7227-8360-8a0185336c54\", \"meta_canonical\": \"\", \"meta_description\": \"Welcome to Laravel\", \"sitemap_priority\": \"0.8\", \"sitemap_changefreq\": \"weekly\", \"meta_featured_image\": [1]}', '2026-09-18 07:54:23', '2026-10-20 01:21:00'),
('01a0c2aa-3562-7226-90c8-290115a491d7', 'english', '01a0b382-6875-7045-aa28-6c187e7728f7', 1, 'published', 'welcome-to-laravel', '', '2026-09-21 13:32', 1, 'pages', 'homepage', '{\"title\": \"Welcome to Laravel\", \"content\": \"<h1>\\\"Homepage\\\" blueprint. Head to the Pages</h1><h2>\\\"Homepage\\\" blueprint. Head to the Pages</h2><p>\\\"Homepage\\\" blueprint. Head to the Pages</p><p>This content is managed from the entry\'s \\\"Homepage\\\" blueprint. Head to the Pages collection in the control panel to edit it.</p><p>Heading</p><ul><li><p>Welcome to Laravel</p></li><li><p>Subheading</p></li></ul><p>This is a dummy homepage — edit or replace it from the Pages collection.</p><ol><li><p>replikators *</p></li><li><p>No entries yet.</p></li><li><p>Add replikators</p></li></ol><p></p>\", \"heading\": \"Welcome to Laravel\", \"subheading\": \"This is a dummy homepage — edit or replace it from the Pages collection.\", \"replikators\": [{\"testing\": \"tessss\", \"_enabled\": true, \"headingx\": \"testss\"}]}', '[]', '{\"robots\": [\"noindex\", \"nofollow\"], \"meta_title\": \"Welcome to Laravel\", \"meta_author\": \"01a0c190-2139-7227-8360-8a0185336c54\", \"meta_canonical\": \"\", \"meta_description\": \"Welcome to Laravel\", \"sitemap_priority\": \"0.8\", \"sitemap_changefreq\": \"weekly\", \"meta_featured_image\": [1]}', '2026-09-21 06:32:09', '2026-09-21 06:54:17'),
('01a13891-699a-70c1-bbeb-7aebf3bd4423', 'default', NULL, 1, 'published', 'about-us', 'about-us', '2026-10-14 10:59', NULL, 'pages', 'about', '{\"test\": \"About Us\", \"title\": \"About Us\", \"taxonomy_select\": [\"1\"]}', '[]', '{\"robots\": [\"noindex\", \"nofollow\"], \"meta_title\": \"About Us\", \"meta_author\": \"01a0b382-6863-72bd-a2ae-ebc31520aba8\", \"meta_canonical\": \"\", \"meta_description\": \"About Us\", \"sitemap_priority\": \"0.8\", \"sitemap_changefreq\": \"weekly\", \"meta_featured_image\": [7]}', '2026-10-14 04:00:16', '2026-10-14 04:00:16'),
